fn main() -> Result<(), Box<dyn std::error::Error>> {
    let out = std::path::PathBuf::from(std::env::var("OUT_DIR").unwrap());

    let proto_files = ["proto/orchestration.proto", "proto/chat.proto"];
    let mut any_compiled = false;

    for proto_path in &proto_files {
        if !std::path::Path::new(proto_path).exists() {
            continue;
        }
        any_compiled = true;
    }

    if !any_compiled {
        eprintln!("cargo:warning=No proto files found, skipping gRPC codegen");
        return Ok(());
    }

    let existing: Vec<&str> = proto_files
        .iter()
        .copied()
        .filter(|p| std::path::Path::new(p).exists())
        .collect();

    tonic_build::configure()
        .build_server(true)
        .build_client(true)
        .file_descriptor_set_path(out.join("op_chat_descriptor.bin"))
        .out_dir("src/orchestration/proto")
        .compile(&existing, &["proto"])?;

    for proto_path in &existing {
        println!("cargo:rerun-if-changed={}", proto_path);
    }

    Ok(())
}

// ChatService — gRPC façade for the control-plane chatbot.
//
// The chatbot is a delegator, not an executor. It plans, suggests, coordinates,
// and orchestrates — but always delegates execution to agents. Forced tool
// calling is mandatory: even user-facing responses are emitted as tool calls.
//
// threetched owns LLM provider/model routing (OD-28). SendRequest carries
// the provider/model selection from threetched's state; the server does not
// make routing decisions.
//
// Wire vocabulary mirrors AI SDK UIMessage part kinds so renderers stay
// portable, but the producer is our own runtime — no AI SDK provider library.

syntax = "proto3";

package op_chat.chat;

// ============================================================================
// CHAT SERVICE
// ============================================================================

service ChatService { … }

// ============================================================================
// REQUESTS
// ============================================================================

message SendRequest { … }

message ApproveRequest { … }

message CancelRequest {
  string conversation_id = 1;
}

// ============================================================================
// STREAM FRAMES
// ============================================================================

message ChatFrame { … }

message UIMessagePart { … }

message ApprovalRequired { … }

message StreamError { … }

message Heartbeat {
  uint64 server_time_ms = 1;
}

message StreamDone { … }

// ============================================================================
// RESPONSES
// ============================================================================

message ApproveResponse { … }

message CancelResponse { … }

