//! ChatService gRPC server implementation.
//!
//! Implements the `op_chat.chat.ChatService` trait from `chat.proto`.
//!
//! Architecture:
//! - threetched owns provider/model routing (OD-28) — SendRequest carries them.
//! - gemma_brain routes to the selected model and applies compliance tags.
//! - The chatbot is a DELEGATOR — forced tool calling is mandatory; even user
//!   responses are emitted as tool calls (respond_to_user).
//! - Chat persistence flows through the memory loop → cognitive.
//! - The agent loop is bounded (≥50 steps) and cancellable.

use std::pin::Pin;
use std::sync::Arc;

use tokio::sync::Mutex;
use tokio_stream::Stream;
use tokio_stream::wrappers::ReceiverStream;
use tonic::{Request, Response, Status};
use tracing::{info, warn};

use crate::orchestration::proto::op_chat_chat::{
    ApproveRequest, ApproveResponse, CancelRequest, CancelResponse, ChatFrame, Heartbeat,
    SendRequest, StreamDone, UiMessagePart, chat_frame, chat_service_server::ChatService,
};

/// Shared state for the ChatService.
pub struct ChatServiceImpl {
    /// Active conversation cursors for cancel support.
    cancellations: Arc<Mutex<std::collections::HashMap<String, tokio::sync::watch::Sender<bool>>>>,
    /// Pending approvals: tool_call_id -> oneshot sender.
    approvals: Arc<Mutex<std::collections::HashMap<String, tokio::sync::oneshot::Sender<bool>>>>,
}

impl ChatServiceImpl {
    pub fn new() -> Self { … }
}

impl Default for ChatServiceImpl {
    fn default() -> Self {
        Self::new()
    }
}

type ChatStream = Pin<Box<dyn Stream<Item = Result<ChatFrame, Status>> + Send + 'static>>;

#[async_trait::async_trait]
impl ChatService for ChatServiceImpl { … }

/// Base system prompt with anti-hallucination rules (FIXED - NOT EDITABLE)
const FIXED_BASE_PROMPT: &str = r#"3tched AI infrastructure platform — Artix Linux, runit service supervision (controlled with `sv`), Incus containers, OVS switching fabric, WARP identity transport (WireGuard terminates at the decoy).

Capabilities:
…
7. Report actual tool results, not imagined outcomes
"#;

//!
//! Architecture:
//! - threetched owns provider/model routing (OD-28) — SendRequest carries them.
//! - gemma_brain routes to the selected model and applies compliance tags.
//! - The chatbot is a DELEGATOR — forced tool calling is mandatory; even user
//!   responses are emitted as tool calls (respond_to_user).
//! - Chat persistence flows through the memory loop → cognitive.
//! - The agent loop is bounded (≥50 steps) and cancellable.

use std::pin::Pin;

//! Chat Actor - Central message processor
//!
//! The ChatActor is the "brain" of op-dbus-v2. It:
//! - Receives RPC requests from various frontends (web, MCP, CLI)
//! - Routes requests to appropriate handlers (tools, D-Bus, LLM)
//! - Manages sessions and conversation state
//! - **Executes tools with full tracking and accountability**
//! - Uses ForcedToolPipeline for anti-hallucination chat

use anyhow::Result;
use op_execution_tracker::ExecutionTracker;
use op_llm::provider::{ChatMessage as LlmChatMessage, LlmProvider};
use op_tools::ToolRegistry;
use serde::{Deserialize, Serialize};
use simd_json::{OwnedValue as Value, json};
use std::sync::Arc;
use tokio::sync::{mpsc, oneshot};
use tracing::{debug, error, info, warn};

use crate::forced_tool_pipeline::ForcedToolPipeline;
use crate::memory_loop::{CHATBOT_SOUL_ID, MemoryLoop};
use crate::session::SessionManager;
use crate::system_prompt::generate_system_prompt;
use crate::tool_executor::TrackedToolExecutor;

const DEFAULT_MAX_PROMPT_TOKENS: usize = 200_000;
const DEFAULT_MAX_MESSAGE_CHARS: usize = 80_000;

/// Configuration for ChatActor
#[derive(Debug, Clone)]
pub struct ChatActorConfig {
    /// Maximum concurrent requests
    pub max_concurrent: usize,
    /// Request timeout in seconds
    pub request_timeout_secs: u64,
    /// Enable execution tracking
    pub enable_tracking: bool,
    /// Maximum execution history to keep
    pub max_history: usize,
    /// Default LLM model to use
    pub default_model: String,
}

impl Default for ChatActorConfig {
    fn default() -> Self {
        Self {
            max_concurrent: 10,
            request_timeout_secs: 300,
            enable_tracking: true,
            max_history: 1000,
            default_model: "default".to_string(),
        }
    }
}

/// RPC Request types
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum RpcRequest {
    /// List available tools
    ListTools {
        #[serde(default)]
        offset: Option<usize>,
        #[serde(default)]
        limit: Option<usize>,
    },

    /// Execute a tool
    ExecuteTool {
        name: String,
        arguments: Value,
        #[serde(default)]
        session_id: Option<String>,
    },

    /// Get tool definition
    GetTool { name: String },

    /// Chat with LLM
    Chat {
        message: String,
        session_id: String,
        #[serde(default)]
        model: Option<String>,
        #[serde(default)]
        container_id: Option<String>,
    },

    /// Get execution history
    GetHistory {
        #[serde(default)]
        limit: Option<usize>,
    },

    /// Get execution statistics
    GetStats,

    /// Health check
    Health,

    /// Introspect D-Bus service
    Introspect {
        service: String,
…
    },
…
}

//! Natural Language Server Administration
//!
//! This is the CORE module that enables natural language server administration.
//! It coordinates between:
//! - LLM (understands user intent)
//! - Tool Registry (executes operations)
//! - Response formatting (user-friendly output)
//!
//! The key insight: We instruct the LLM via system prompt to ALWAYS use tools,
//! then parse and execute those tool calls.

use anyhow::{Context, Result};
use regex::Regex;
use serde::{Deserialize, Serialize};
use simd_json::OwnedValue as Value;
use simd_json::prelude::*;
use std::sync::Arc;
use tracing::{debug, error, info, warn};

use op_llm::provider::{
    ChatMessage, ChatRequest, ChatResponse, LlmProvider, ToolChoice, ToolDefinition,
};
use op_tools::ToolRegistry;

/// Extracted tool call from LLM response
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExtractedToolCall {
    pub name: String,
    pub arguments: Value,
    pub source: ToolCallSource,
}

/// Where the tool call was extracted from
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ToolCallSource {
    /// Native tool_calls from LLM API
    Native,
    /// Parsed from <tool_call> tags in text
    XmlTags,
    /// Parsed from ```tool format in text
    CodeBlock,
    /// Parsed from JSON in text
    JsonInText,
}

/// Result of natural language admin operation
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NLAdminResult {
    /// User-friendly response message
    pub message: String,
    /// Whether operation was successful
    pub success: bool,
    /// Tools that were executed
    pub tools_executed: Vec<String>,
    /// Detailed results from each tool
    pub tool_results: Vec<ToolExecutionResult>,
    /// Raw LLM response (for debugging)
    pub llm_response: Option<String>,
}

/// Result of a single tool execution
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolExecutionResult {
    pub tool_name: String,
    pub success: bool,
    pub result: Option<Value>,
    pub error: Option<String>,
}

/// Tool call parser - extracts tool calls from LLM responses
pub struct ToolCallParser {
    /// Regex for <tool_call>name(args)</tool_call> format
    xml_tag_regex: Regex,
    /// Regex for ```tool\nname(args)\n``` format
    code_block_regex: Regex,
    /// Regex for function call format: tool_name({"arg": "value"})
    function_call_regex: Regex,
}

impl Default for ToolCallParser {
    fn default() -> Self {
        Self::new()
    }
}

impl ToolCallParser {
    pub fn new() -> Self {
        Self {
            // Matches: <tool_call>tool_name({"arg": "value"})</tool_call>
            // Also handles nested JSON with newlines using (?s) for DOTALL mode
            xml_tag_regex: Regex::new(
                r"(?s)<tool_call>\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*\((.*?)\)\s*</tool_call>",
            )
            .expect("hardcoded regex pattern is valid"),
            // Matches: ```tool\ntool_name({"arg": "value"})\n```
            // Also handles ```tool_code format
            code_block_regex: Regex::new(r"(?s)```(?:tool|tool_code)\s*\n(.+?)\n```")
                .expect("hardcoded regex pattern is valid"),
            // Matches: tool_name({"arg": "value"}) or tool_name({multi-line json})
            function_call_regex: Regex::new(
                r"(?s)\b([a-zA-Z_][a-zA-Z0-9_]*)\s*\(\s*(\{.*?\})\s*\)",
            )
            .expect("hardcoded regex pattern is valid"),
        }
    }
…
}

