//! Forced Tool Execution - Anti-Hallucination Architecture
//!
//! This module ensures the LLM CANNOT hallucinate by:
//! 1. Requiring all output to go through response tools
//! 2. Verifying claimed actions against execution log
//! 3. Detecting and flagging hallucination attempts
//!
//! ## How It Works
//!
//! ```text
//! User: "Create a bridge called br0"
//!         │
//!         ▼
//! ┌───────────────────────────────────────────────────────────┐
//! │ LLM Response (MUST contain tool_calls)                    │
//! │                                                           │
//! │ tool_calls: [                                             │
//! │   { name: "ovs_create_bridge", args: {name: "br0"} },    │
//! │   { name: "respond_to_user", args: {                      │
//! │       message: "Created bridge br0",                      │
//! │       message_type: "success",                            │
//! │       related_actions: ["ovs_create_bridge"]              │
//! │   }}                                                      │
//! │ ]                                                         │
//! └───────────────────────────────────────────────────────────┘
//!         │
//!         ▼
//! ┌───────────────────────────────────────────────────────────┐
//! │ Execution Verifier                                        │
//! │                                                           │
//! │ ✓ ovs_create_bridge was called                            │
//! │ ✓ respond_to_user references ovs_create_bridge            │
//! │ ✓ No raw text output (all via respond_to_user)            │
//! │                                                           │
//! │ Result: VERIFIED - No hallucination                       │
//! └───────────────────────────────────────────────────────────┘
//! ```

use anyhow::Result;
// use op_core::ExecutionTracker;
use serde::{Deserialize, Serialize};
use simd_json::OwnedValue;
use simd_json::OwnedValue as Value;
use simd_json::prelude::*;
use std::collections::HashSet;
use std::sync::Arc;
use tracing::error;

use crate::tool_executor::TrackedToolExecutor;
use op_tools::builtin::response_tools::get_response_accumulator;

/// Result of hallucination detection
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct HallucinationCheck {
    /// Whether the response passed verification
    pub verified: bool,
    /// Detected hallucination issues
    pub issues: Vec<HallucinationIssue>,
    /// Tools that were actually executed
    pub executed_tools: Vec<String>,
    /// Tools claimed in response but not executed
    pub unverified_claims: Vec<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct HallucinationIssue {
    pub issue_type: HallucinationType,
    pub description: String,
    pub severity: IssueSeverity,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum HallucinationType {
    /// LLM output raw text without using respond_to_user
    RawTextOutput,
    /// Claimed to perform action without calling tool
    UnverifiedActionClaim,
    /// respond_to_user called without any action tools
    ResponseWithoutAction,
    /// Tool call failed but success was claimed
    FailedToolClaimedSuccess,
    /// No respond_to_user tool called
    NoResponseTool,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, PartialOrd, Ord)]
#[serde(rename_all = "snake_case")]
pub enum IssueSeverity {
    /// Informational - not necessarily wrong
    Info,
    /// Warning - suspicious but might be valid
    Warning,
    /// Error - definite hallucination
    Error,
    /// Critical - severe hallucination, response should be rejected
    Critical,
}

/// Forced execution orchestrator
///
/// Ensures all LLM interactions go through tools and verifies
/// that claimed actions actually occurred.

//! Forced Tool Execution Pipeline
//!
//! This is the MISSING INTEGRATION that connects:
//! - LLM requests (with tools and tool_choice: required)
//! - Tool execution tracking
//! - Hallucination verification
//! - Response extraction
//!
//! ## The Problem
//!
//! The existing code has:
//! - `ForcedExecutionOrchestrator` - tracks and verifies tool calls
//! - `response_tools` - respond_to_user, cannot_perform, etc.
//! - `TrackedToolExecutor` - executes tools with metrics
//!
//! But NOTHING connects them to the LLM request! The LLM is free to
//! output raw text because:
//! 1. `tool_choice` is not set to "required"
//! 2. Tools are not passed in the request
//! 3. Responses are not verified before returning
//!
//! ## The Solution
//!
//! This pipeline:
//! 1. Forces `tool_choice: required` on every LLM request
//! 2. Passes all available tools (action + response tools)
//! 3. Executes tool_calls via ForcedExecutionOrchestrator
//! 4. Verifies the turn for hallucinations
//! 5. Extracts user response from respond_to_user tool only

use anyhow::{Context, Result};
use simd_json::json;
use std::sync::Arc;
use tracing::{debug, error, info, warn};

use op_llm::provider::{
    ChatMessage, ChatRequest, ChatResponse, LlmProvider, ToolChoice, ToolDefinition,
};
use op_tools::ToolRegistry;

use crate::agent_tools::register_context_agents;
use crate::forced_execution::{
    ForcedExecutionOrchestrator, HallucinationCheck, ToolCall, detect_raw_text_output,
};
use crate::tool_executor::TrackedToolExecutor;

/// Maximum turns in a single request (tool call loops)
const MAX_TOOL_TURNS: usize = 10;

/// Result of processing a user message
#[derive(Debug)]
pub struct PipelineResult {
    /// The final user-facing response
    pub response: String,
    /// Whether the response was verified (no hallucinations)
    pub verified: bool,
    /// Hallucination check details
    pub hallucination_check: HallucinationCheck,
    /// Tools that were executed
    pub executed_tools: Vec<String>,
    /// Raw LLM response (for debugging)
    pub raw_llm_response: Option<ChatResponse>,
}

/// Forced Tool Execution Pipeline
///
/// This is the main integration point that ensures:
/// - LLM MUST use tools (tool_choice: required)
/// - All tool calls are tracked and verified
/// - Hallucinations are detected and rejected
/// - Only respond_to_user output reaches the user
pub struct ForcedToolPipeline {
    tool_registry: Arc<ToolRegistry>,
    orchestrator: ForcedExecutionOrchestrator,
}

impl ForcedToolPipeline {
    /// Create new pipeline
    pub fn new(tool_registry: Arc<ToolRegistry>, executor: Arc<TrackedToolExecutor>) -> Self {
        Self {
            tool_registry,
            orchestrator: ForcedExecutionOrchestrator::new(executor),
        }
    }

    /// Get all tool definitions for LLM request
    async fn get_tool_definitions(&self) -> Vec<ToolDefinition> {
        let tools = self.tool_registry.list().await;

        tools
            .into_iter()
            .map(|tool| ToolDefinition {
                name: tool.name.clone(),
                description: tool.description.clone(),
                input_schema: tool.input_schema.clone(),
                schema_version: String::new(),
                category: tool.category.clone(),
                tags: tool.tags.clone(),
                namespace: tool.namespace.clone(),
            })
            .collect()
    }

…
}

